const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function save(){localStorage.setItem("ocm_completed",JSON.stringify(completed));localStorage.setItem("ocm_bookmarks",JSON.stringify(bookmarks));localStorage.setItem("ocm_notes",JSON.stringify(notes));updateProgress()}
function updateProgress(){let p=Math.round(completed.length/Math.max(allTopics.length,1)*100);$("#progressNumber").textContent=p+"%";$("#progressBar").style.width=p+"%";$("#progressText").textContent=completed.length?`${completed.length} topics completed — keep building momentum`:"Your learning journey starts here"}
function moduleCards(container,limit=modules.length){$(container).innerHTML=modules.slice(0,limit).map((m,i)=>`<button class="module-card" data-module="${i}" style="--accent:${m.accent};--tint:${m.tint}"><span class="module-number">${String(i+1).padStart(2,"0")}</span><span class="module-symbol">${m.icon}</span><b>${esc(m.title)}</b><p>${esc(m.short)}</p><span class="card-bottom"><span>${m.topics.length} learning topics</span><span>↗</span></span></button>`).join("");}
function buildNav(){ $("#moduleNav").innerHTML=modules.map((m,i)=>`<button class="module-nav-item" data-module="${i}"><span class="module-n">${String(i+1).padStart(2,"0")}</span><span>${esc(m.title)}</span></button>`).join(""); }
function setView(view){currentView=view;$("#sidebar").classList.remove("open");document.querySelectorAll("[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));const names={home:"Dashboard",modules:"Curriculum",quiz:"Quiz center",tools:"Chemistry tools",exam:"Exam preparation",notes:"My notes & bookmarks",search:"Search results",topic:currentTopic};$("#crumbCurrent").textContent=names[view]||"Learning space";renderView()}
function openModule(i){currentView="module";$("#crumbCurrent").textContent=modules[i].title;$("#sidebar").classList.remove("open");document.querySelectorAll(".module-nav-item").forEach((b,j)=>b.classList.toggle("active",i===j));renderModule(i)}
function openTopic(t){currentTopic=t;currentView="topic";$("#crumbCurrent").textContent=t;$("#sidebar").classList.remove("open");renderTopic(t)}
function renderView(){const c=$("#content");if(currentView==="home"){c.innerHTML=homeTemplate();moduleCards("#homeModules",8);updateProgress();return}if(currentView==="modules"){c.innerHTML=`<div class="eyebrow">THE COMPLETE LEARNING PATH</div><h1 class="page-title">Organic Chemistry Curriculum</h1><p class="page-subtitle">A progressive route from basic concepts to reaction mechanisms, spectroscopy, and exam practice. Select a module to explore its topic list.</p><div class="module-grid" id="allModules"></div>`;moduleCards("#allModules");return}if(currentView==="quiz"){renderQuiz();return}if(currentView==="tools"){renderTools();return}if(currentView==="exam"){renderExam();return}if(currentView==="notes"){renderNotes();return}if(currentView==="search"){renderSearch($("#sidebarSearch").value);return}if(currentView==="module"){return}}
function homeTemplate(){return `<div class="welcome-row"><div><div class="eyebrow"><span class="pulse"></span> YOUR ORGANIC CHEMISTRY WORKSPACE</div><h1>Master Organic<br><span class="gradient-text">Chemistry.</span></h1><p class="hero-copy">Understand the logic behind molecules, reactions, and mechanisms — from your first carbon atom to advanced concepts.</p><div class="hero-actions"><button class="primary-btn" data-topic="What is Organic Chemistry">Continue learning <span>→</span></button><button class="secondary-btn" data-view="modules">Explore curriculum</button></div><div class="trust-row"><span>✓ Structured learning path</span><span>✓ Practice as you learn</span><span>✓ BS Chemistry focused</span></div></div><div class="hero-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><svg class="molecule" viewBox="0 0 360 300" aria-label="Molecular structure"><g stroke="#4bd5c5" stroke-width="2.2" fill="none"><path d="M178 143 119 106 65 139 68 204 128 231 183 199 178 143 238 108 292 141 287 203 229 231 183 199"/><path d="M119 106 126 45 181 22 238 47 238 108M65 139 18 113M292 141 331 106M287 203 324 237M128 231 113 276"/></g><g fill="#0c2b40" stroke="#4bd5c5" stroke-width="2"><circle cx="178" cy="143" r="22"/><circle cx="119" cy="106" r="15"/><circle cx="65" cy="139" r="13"/><circle cx="68" cy="204" r="13"/><circle cx="128" cy="231" r="15"/><circle cx="183" cy="199" r="16"/><circle cx="238" cy="108" r="17"/><circle cx="292" cy="141" r="14"/><circle cx="287" cy="203" r="14"/><circle cx="229" cy="231" r="12"/><circle cx="181" cy="22" r="12"/><circle cx="238" cy="47" r="12"/><circle cx="119" cy="45" r="11"/></g><g fill="#f4fbff" font-weight="700" font-size="12" text-anchor="middle"><text x="178" y="147">C</text><text x="119" y="110">O</text><text x="238" y="112">N</text><text x="128" y="235">C</text></g></svg><div class="floating-label label-a"><span class="mini-dot teal"></span> Molecular logic</div><div class="floating-label label-b"><span class="mini-dot gold"></span> Reaction pathways</div><div class="art-caption">STRUCTURE → PROPERTY → REACTIVITY</div></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top"><span>Curriculum modules</span><span class="stat-icon cyan">▦</span></div><div class="stat-number">22</div><div class="stat-foot">From fundamentals to spectroscopy</div></div><div class="stat-card"><div class="stat-top"><span>Topics to explore</span><span class="stat-icon purple">⌘</span></div><div class="stat-number">120+</div><div class="stat-foot">Search, study, and revise</div></div><div class="stat-card"><div class="stat-top"><span>Your progress</span><span class="stat-icon gold">↗</span></div><div class="stat-number" id="progressNumber">0%</div><div class="progress-track"><span id="progressBar"></span></div><div class="stat-foot" id="progressText">Your learning journey starts here</div></div></div><div class="section-heading"><div><div class="eyebrow">YOUR LEARNING PATH</div><h2>Explore the curriculum</h2><p>Choose a module and build your understanding step by step.</p></div><button class="text-button" data-view="modules">View all modules <span>→</span></button></div><div class="module-grid" id="homeModules"></div><div class="section-heading compact-heading"><div><div class="eyebrow">LEARN BY DOING</div><h2>Practice makes concepts stick</h2></div></div><div class="practice-grid"><button class="practice-card" data-view="quiz"><span class="practice-icon pink">✳</span><span><b>Quiz center</b><small>Test concepts with instant explanations.</small></span><span class="arrow">↗</span></button><button class="practice-card" data-view="tools"><span class="practice-icon teal">⚗</span><span><b>Chemistry tools</b><small>Explore formula mass and key concepts.</small></span><span class="arrow">↗</span></button><button class="practice-card" data-view="exam"><span class="practice-icon gold">▤</span><span><b>Exam preparation</b><small>Revise definitions, reactions, and exam points.</small></span><span class="arrow">↗</span></button></div><footer>Organic Chemistry Mastery <span>Built for curious minds · Verify advanced chemistry with trusted textbooks.</span></footer>`}
function renderModule(i){const m=modules[i];$("#content").innerHTML=`<div class="eyebrow">MODULE ${String(i+1).padStart(2,"0")} · LEARNING PATH</div><h1 class="page-title">${esc(m.title)}</h1><p class="page-subtitle">${esc(m.short)} Start with the fundamentals, then move to more demanding applications.</p><div class="panel"><div class="tag-row"><span class="tag">BEGINNER → ADVANCED</span><span class="tag gold-tag">${m.topics.length} TOPICS</span></div><h3>What you will learn</h3><p>This module is arranged to build concepts in a logical order. Open any topic for a guided explanation, worked examples, common mistakes, exam notes, and practice.</p><div class="progress-track"><span style="width:${Math.round(m.topics.filter(t=>completed.includes(t)).length/m.topics.length*100)}%"></span></div><small style="color:var(--muted)">${m.topics.filter(t=>completed.includes(t)).length} of ${m.topics.length} topics completed</small></div><div class="topic-list">${m.topics.map((t,j)=>`<button class="topic-link" data-topic="${esc(t)}"><div><b>${esc(t)}</b><small>${completed.includes(t)?"✓ Completed":"Read lesson · examples · quiz"}</small></div><span>→</span></button>`).join("")}</div><div class="topic-actions"><button class="small-btn" data-view="quiz">Practice this module ↗</button><button class="small-btn" data-view="modules">Back to all modules</button></div>`}
function getData(t){if(topicData[t])return topicData[t];if(t.toLowerCase().includes("isomer"))return topicData["Definition of Isomerism"];if(t.toLowerCase().includes("carbon"))return topicData["What is Carbon"];if(t.toLowerCase().includes("markovnikov"))return topicData["Markovnikov's Rule"];if(t.toLowerCase().includes("sn1"))return topicData["SN1 Mechanism"];if(t.toLowerCase().includes("sp³")||t.toLowerCase().includes("sp3"))return topicData["sp³ Hybridization"];return null}
function translatedText(t,lang){if(lang==="en")return t;const dictionary={"What is Organic Chemistry":{ur:"نامیاتی کیمسٹری کاربن کے مرکبات، ان کی ساخت، خصوصیات، تعاملات اور تیاری کا مطالعہ ہے۔",roman:"Organic chemistry carbon ke compounds, unki structure, properties, reactions aur preparation ka mutala hai."},"Definition of Isomerism":{ur:"آئسومرزم وہ مظہر ہے جس میں مرکبات کا سالماتی فارمولا ایک جیسا ہوتا ہے، لیکن ایٹموں کی ترتیب یا خلا میں ان کی ترتیب مختلف ہوتی ہے۔",roman:"Isomerism woh phenomenon hai jisme compounds ka molecular formula same hota hai lekin atoms ki connectivity ya 3D arrangement mukhtalif hoti hai."},"Chain Isomerism":{ur:"چین آئسومرزم میں سالماتی فارمولا ایک جیسا ہوتا ہے لیکن کاربن چین کی شاخ بندی مختلف ہوتی ہے۔",roman:"Chain isomerism mein molecular formula same hota hai lekin carbon chain ki branching different hoti hai."},"Position Isomerism":{ur:"پوزیشن آئسومرزم میں ایک ہی فنکشنل گروپ یا ملٹی پل بانڈ کاربن چین میں مختلف جگہ پر ہوتا ہے۔",roman:"Position isomerism mein same functional group ya multiple bond carbon chain par mukhtalif position par hota hai."},"Functional Group Isomerism":{ur:"فنکشنل گروپ آئسومرزم میں سالماتی فارمولا ایک جیسا لیکن فنکشنل گروپ مختلف ہوتا ہے۔",roman:"Functional group isomerism mein molecular formula same hota hai magar functional groups different hotay hain."},"What is Carbon":{ur:"کاربن ایک کیمیائی عنصر ہے جس کی علامت C اور ایٹمی نمبر 6 ہے۔ یہ عموماً چار کوویلنٹ بانڈ بنا سکتا ہے۔",roman:"Carbon aik chemical element hai jis ka symbol C aur atomic number 6 hai. Yeh aam tor par chaar covalent bonds bana sakta hai."}};return dictionary[t]?.[lang]|| (lang==="ur"?"اس موضوع کو سمجھنے کے لیے پہلے اس کی بنیادی تعریف، پھر ساخت اور مثالوں کا مطالعہ کریں۔": "Is topic ko samajhne ke liye pehle basic definition, phir structure aur examples ka mutala karein.");}
function renderTopic(t){const data=getData(t);const lang=$("#languageSelect").value;const m=allTopics.find(x=>x.title===t);let content;if(data){content=`<div class="tag-row"><span class="tag">GUIDED LESSON</span><span class="tag gold-tag">BS CHEMISTRY</span></div><h2>${esc(t)}</h2><p>${esc(translatedText(t,lang))}</p><div class="panel"><h3>1 · Very simple explanation</h3><p>${esc(data.simple)}</p><h4>2 · Scientific definition</h4><p>${esc(data.definition)}</p><h4>3 · Introduction & detailed concept</h4><p>${esc(data.intro)}</p><p>${esc(data.advanced)}</p></div><div class="panel"><h3>4 · Structure / formula</h3><div class="formula">${esc(data.formula).replace(/\n/g,"<br>")}</div><p>Read structural formulas by tracking which atoms are connected. In condensed formulas, groups such as CH₃ and OH represent connected atoms.</p></div><div class="panel"><h3>5 · Step-by-step understanding</h3><ol class="steps">${data.steps.map(s=>`<li>${esc(s)}</li>`).join("")}</ol></div><div class="panel"><h3>6 · Examples</h3><ul>${data.examples.map(s=>`<li>${esc(s)}</li>`).join("")}</ul></div><div class="panel"><h3>7 · Common mistakes</h3><ul>${data.mistakes.map(s=>`<li>${esc(s)}</li>`).join("")}</ul><h4>8 · Exam point</h4><p><b>${esc(data.exam)}</b></p></div>`}else{content=`<div class="tag-row"><span class="tag">CURRICULUM TOPIC</span><span class="tag gold-tag">BEGINNER → ADVANCED</span></div><h2>${esc(t)}</h2><div class="panel"><h3>1 · Start with the core idea</h3><p>This lesson is part of the Organic Chemistry Mastery curriculum. Use the guiding framework below to study the topic accurately and progressively.</p><h4>Learning sequence</h4><ol class="steps"><li>Write a concise definition and identify the relevant functional group, bond, species, or principle.</li><li>Draw a correctly labelled structure and write the molecular or condensed formula where applicable.</li><li>Explain the electronic basis: bond polarity, resonance, inductive effects, steric effects, or orbital interactions as relevant.</li><li>Work through a standard example, stating reagents, conditions, major product, and selectivity.</li><li>Compare the concept with closely related ideas and note important exceptions.</li></ol></div><div class="panel"><h3>2 · BS Chemistry study checklist</h3><ul><li>Definition and key terminology</li><li>Structure and bonding representation</li><li>Representative examples and counterexamples</li><li>Reaction equation and conditions, if applicable</li><li>Mechanistic reasoning and electron movement, if applicable</li><li>Applications, common mistakes, and exam-ready summary</li></ul><p><b>Accuracy note:</b> This starter edition provides full worked lessons for selected core concepts. Other curriculum entries are structured lesson guides rather than fully written textbook chapters; verify advanced details against your course textbook.</p></div>`}$("#content").innerHTML=`<div class="eyebrow">LEARNING PATH / ${esc(m?m.module:"CORE CONCEPTS")}</div><div class="topic-content">${content}<div class="topic-actions"><button class="small-btn ${completed.includes(t)?"saved":""}" data-complete="${esc(t)}">${completed.includes(t)?"✓ Marked complete":"✓ Mark as completed"}</button><button class="small-btn ${bookmarks.includes(t)?"saved":""}" data-bookmark="${esc(t)}">${bookmarks.includes(t)?"★ Bookmarked":"☆ Bookmark topic"}</button><button class="small-btn" data-view="quiz">Test your knowledge ↗</button></div><div class="panel"><h3>Quick check</h3><p id="quickQuestion">${quickQuestion(t)}</p><div id="quickOptions">${quickOptions(t)}</div><div id="quickFeedback"></div></div><div class="panel"><h3>Your notes</h3><textarea class="note-area" id="topicNote" placeholder="Write your own explanation, confusing points, or exam notes...">${esc(notes[t]||"")}</textarea><div class="topic-actions"><button class="small-btn" id="saveNote">Save notes</button><button class="small-btn" data-view="notes">View all notes</button></div></div></div>`}
function quickQuestion(t){if(t.toLowerCase().includes("isomer"))return "Which statement must be true for a pair of isomers?";if(t.toLowerCase().includes("hybrid"))return "What is the ideal geometry associated with sp³ hybridization?";if(t.toLowerCase().includes("sn1"))return "Which intermediate is characteristic of an SN1 mechanism?";if(t.toLowerCase().includes("carbon"))return "What is the atomic number of carbon?";return "What is the best first step when studying a new organic chemistry topic?"}
function quickOptions(t){let opts=t.toLowerCase().includes("isomer")?["They always have different formulas","They have the same molecular formula","They always have the same properties"]:t.toLowerCase().includes("hybrid")?["Linear","Trigonal planar","Tetrahedral"]:t.toLowerCase().includes("sn1")?["Carbocation","Carbanion","Carbene"]:t.toLowerCase().includes("carbon")?["4","6","8"]:["Memorize without understanding","Define the concept and identify its structure","Skip reaction conditions"];let ans=1;if(t.toLowerCase().includes("sn1"))ans=0;return opts.map((o,i)=>`<button class="quiz-option" data-quick="${i}" data-correct="${i===ans}" data-why="${esc(i===ans?"Correct. This is the key defining idea for this question.":"Review the definition and structural evidence, then try again.")}">${esc(o)}</button>`).join("")}
function renderQuiz(){const q=quizQuestions[quizOrder[quizIndex%quizOrder.length]];$("#content").innerHTML=`<div class="eyebrow">RETRIEVAL PRACTICE</div><h1 class="page-title">Quiz center</h1><p class="page-subtitle">Answer one question at a time. Each response includes a reason so you learn from both correct and incorrect answers.</p><div class="panel" style="max-width:760px"><div class="tag-row"><span class="tag">MIXED TOPICS</span><span class="tag gold-tag">QUESTION ${quizIndex+1} / ${quizQuestions.length}</span></div><div class="progress-track"><span style="width:${(quizIndex+1)/quizQuestions.length*100}%"></span></div><h3 style="font-size:18px;line-height:1.5;margin-top:20px">${esc(q.q)}</h3>${q.opts.map((o,i)=>`<button class="quiz-option" data-answer="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join("")}<div id="quizFeedback"></div><div class="topic-actions"><button class="primary-btn" id="nextQuestion" disabled>${quizIndex===quizQuestions.length-1?"See results":"Next question"} <span>→</span></button><button class="small-btn" id="restartQuiz">Restart quiz</button></div><div class="result-grid"><div class="result-cell"><small>Score so far</small><b id="quizScore">${quizScore}</b></div><div class="result-cell"><small>Questions answered</small><b id="quizAnswered">${quizIndex}</b></div><div class="result-cell"><small>Best habit</small><b>Read why</b></div></div></div>`;quizAnswered=false}
function answerQuiz(i){if(quizAnswered)return;quizAnswered=true;const q=quizQuestions[quizOrder[quizIndex%quizOrder.length]],ok=i===q.answer;if(ok)quizScore++;document.querySelectorAll("[data-answer]").forEach((b,j)=>{b.disabled=true;if(j===q.answer)b.classList.add("correct");else if(j===i)b.classList.add("wrong")});$("#quizFeedback").innerHTML=`<div class="feedback"><b>${ok?"Correct!":"Not quite."}</b> ${esc(q.why)}</div>`;$("#quizScore").textContent=quizScore;$("#quizAnswered").textContent=quizIndex+1;$("#nextQuestion").disabled=false}
function nextQuiz(){if(!quizAnswered)return;if(quizIndex===quizQuestions.length-1){const pct=Math.round(quizScore/quizQuestions.length*100);$("#content").innerHTML=`<div class="eyebrow">QUIZ COMPLETE</div><h1 class="page-title">Your results</h1><div class="panel" style="max-width:650px;text-align:center;padding:35px"><div class="stat-icon cyan" style="margin:auto;width:55px;height:55px;font-size:24px">✓</div><div class="stat-number" style="font-size:45px">${pct}%</div><h3>${quizScore>=6?"Strong work!":"Good practice — keep going."}</h3><p>You answered ${quizScore} out of ${quizQuestions.length} questions correctly. Review the explanations and retake the quiz to strengthen recall.</p><button class="primary-btn" id="restartQuiz">Try again <span>↻</span></button></div>`;return}quizIndex++;renderQuiz()}
function renderTools(){$("#content").innerHTML=`<div class="eyebrow">INTERACTIVE STUDY DESK</div><h1 class="page-title">Chemistry tools</h1><p class="page-subtitle">Lightweight study helpers that work in your browser. Formula mass uses standard approximate atomic weights; it is a calculation aid, not a full chemical database.</p><div class="tool-grid"><div class="panel"><h3>⚗ Molecular formula calculator</h3><p>Enter a formula such as C6H6, H2O, or C2H5OH.</p><input id="formulaInput" class="tool-input" placeholder="e.g. C6H6" value="C6H6"><button class="primary-btn" id="calcFormula">Calculate formula mass <span>→</span></button><div id="formulaResult"></div><small style="color:var(--muted)">Supported syntax: element symbols followed by optional integer counts. Parentheses and hydrates are not yet supported.</small></div><div class="panel"><h3>⌕ Functional-group quick finder</h3><p>Search a functional group to review its general pattern.</p><input id="fgSearch" class="tool-input" placeholder="Try: alcohol, ketone, ester..."><div id="fgResults" class="search-results"></div></div><div class="panel"><h3>↗ Reaction predictor practice</h3><p>Use a common example to practise product prediction.</p><div class="formula">CH₃–CH=CH₂ + HBr</div><p>Under ordinary ionic conditions, which product is expected to be major?</p><button class="quiz-option" data-reaction="wrong">1-bromopropane</button><button class="quiz-option" data-reaction="right">2-bromopropane</button><div id="reactionFeedback"></div><p><small>This is a simplified learning prompt. Real outcomes depend on reagents and conditions.</small></p></div><div class="panel"><h3>◇ Structure & nomenclature practice</h3><p>Choose a structure to practise matching a condensed formula to a name.</p><select id="nameSelect" class="tool-input"><option value="ethanol">CH₃CH₂OH</option><option value="propanone">CH₃COCH₃</option><option value="propene">CH₂=CHCH₃</option><option value="ethanoic">CH₃COOH</option></select><div id="nameResult" class="formula">Ethanol</div><p><small>Suggested names are for simple examples only; this is not a general-purpose IUPAC engine.</small></p></div></div>`;runFormula();runFG("");runName()}
const atomic={H:1.008,C:12.011,N:14.007,O:15.999,F:18.998,Na:22.990,Mg:24.305,P:30.974,S:32.06,Cl:35.45,K:39.098,Ca:40.078,Fe:55.845,Br:79.904,I:126.904};
function runFormula(){let raw=$("#formulaInput")?.value.trim();if(!raw)return;let re=/([A-Z][a-z]?)(\d*)/g,match,counts={},pos=0,valid=true;while((match=re.exec(raw))!==null){if(match.index!==pos){valid=false;break}const el=match[1],n=Number(match[2]||1);if(!atomic[el]||!Number.isInteger(n)||n<1){valid=false;break}counts[el]=(counts[el]||0)+n;pos=re.lastIndex}if(pos!==raw.length||!Object.keys(counts).length)valid=false;if(!valid){$("#formulaResult").innerHTML=`<div class="feedback" style="background:#fff1f1;color:#8b3636">Please enter a supported formula, e.g. C6H6 or C2H5OH. Element symbols are case-sensitive.</div>`;return}let mass=Object.entries(counts).reduce((s,[e,n])=>s+atomic[e]*n,0),atoms=Object.values(counts).reduce((a,b)=>a+b,0);$("#formulaResult").innerHTML=`<div class="result-grid"><div class="result-cell"><small>Formula mass</small><b>${mass.toFixed(3)} g/mol</b></div><div class="result-cell"><small>Elements</small><b>${Object.keys(counts).join(", ")}</b></div><div class="result-cell"><small>Total atoms</small><b>${atoms}</b></div></div><div class="panel" style="padding:12px;margin-top:12px"><b style="font-size:11px">Atom count</b><p>${Object.entries(counts).map(([e,n])=>`${e}: ${n}`).join(" · ")}</p></div>`}
const groups=[["Alkane","C–C single bonds","R–H","Saturated hydrocarbon"],["Alkene","C=C","R₂C=CR₂","Addition reactions"],["Alkyne","C≡C","RC≡CR","Addition reactions"],["Haloalkane","C–X","R–X","Substitution / elimination"],["Alcohol","Hydroxyl","R–OH","Oxidation, dehydration, esterification"],["Ether","C–O–C","R–O–R′","Cleavage under strong acid"],["Aldehyde","Terminal carbonyl","R–CHO","Oxidation and nucleophilic addition"],["Ketone","Internal carbonyl","R–CO–R′","Nucleophilic addition"],["Carboxylic acid","Carboxyl","R–COOH","Acid-base and acyl chemistry"],["Ester","Ester linkage","R–COOR′","Hydrolysis and acyl substitution"],["Amide","Amide linkage","R–CONH₂","Hydrolysis"],["Amine","Amino nitrogen","R–NH₂","Basicity and nucleophilic reactions"],["Nitrile","Cyano","R–C≡N","Hydrolysis and reduction"],["Thiol","Sulfhydryl","R–SH","Oxidation and substitution"],["Phenol","Ar–OH","C₆H₅OH","Aromatic substitution; weak acidity"]];
function runFG(q){const el=$("#fgResults");if(!el)return;const arr=groups.filter(g=>g.join(" ").toLowerCase().includes(q.toLowerCase()));el.innerHTML=arr.length?arr.map(g=>`<div class="topic-link"><div><b>${esc(g[0])}</b><small>${esc(g[1])} · ${esc(g[3])}</small></div><span>${esc(g[2])}</span></div>`).join(""):`<div class="empty-state">No matching functional group found.</div>`}
function runName(){const vals={ethanol:"Ethanol · alcohol · CH₃CH₂OH",propanone:"Propanone · ketone · CH₃COCH₃",propene:"Propene · alkene · CH₂=CHCH₃",ethanoic:"Ethanoic acid · carboxylic acid · CH₃COOH"};if($("#nameResult"))$("#nameResult").textContent=vals[$("#nameSelect").value]}
function renderExam(){$("#content").innerHTML=`<div class="eyebrow">REVISION & EXAM STRATEGY</div><h1 class="page-title">Exam preparation</h1><p class="page-subtitle">Use these structured checklists to prepare answers at BS/BSc level, then extend mechanisms and evidence for advanced courses.</p><div class="tool-grid"><div class="panel"><h3>Core definitions</h3><ul><li>Organic chemistry and organic compounds</li><li>Isomerism and its major classes</li><li>Electrophile, nucleophile, and intermediate</li><li>Resonance and inductive effect</li><li>Hybridization and bond polarity</li></ul></div><div class="panel"><h3>Mechanisms to practise</h3><ul><li>SN1 vs SN2: rate, steps, stereochemistry</li><li>E1 vs E2: conditions and product selectivity</li><li>Electrophilic addition to alkenes</li><li>Electrophilic aromatic substitution</li><li>Nucleophilic addition to carbonyls</li></ul></div><div class="panel"><h3>Long-answer structure</h3><ol><li>Write the definition and principle.</li><li>Draw a labelled structure or equation.</li><li>State reagents and conditions.</li><li>Explain each mechanistic step.</li><li>Discuss selectivity, limitations, and applications.</li></ol></div><div class="panel"><h3>Study plan</h3><p>For each topic, create a one-page revision sheet: definition, structure, mechanism, exceptions, and three practice questions.</p><button class="primary-btn" data-view="quiz">Take a mixed quiz <span>→</span></button></div></div>`}
function renderNotes(){$("#content").innerHTML=`<div class="eyebrow">YOUR PERSONAL STUDY SPACE</div><h1 class="page-title">My notes & bookmarks</h1><p class="page-subtitle">Bookmarks, completion status, and notes are saved in this browser on this device. They are not synced to an account or across devices.</p><div class="tool-grid"><div class="panel"><h3>★ Bookmarked topics (${bookmarks.length})</h3>${bookmarks.length?bookmarks.map(t=>`<button class="topic-link" data-topic="${esc(t)}"><div><b>${esc(t)}</b><small>Open saved topic</small></div><span>→</span></button>`).join(""):`<div class="empty-state">No bookmarks yet.<b>Save topics as you learn.</b></div>`}</div><div class="panel"><h3>▧ Saved notes (${Object.values(notes).filter(v=>v.trim()).length})</h3>${Object.entries(notes).filter(([t,n])=>n.trim()).map(([t,n])=>`<button class="topic-link" data-topic="${esc(t)}"><div><b>${esc(t)}</b><small>${esc(n.slice(0,70))}${n.length>70?"…":""}</small></div><span>→</span></button>`).join("")||`<div class="empty-state">No notes saved yet.<b>Open any topic and write a note.</b></div>`}</div><div class="panel"><h3>✓ Completed topics (${completed.length})</h3><p>${completed.length?completed.map(t=>esc(t)).join(" · "):"Your completed topics will appear here."}</p><button class="small-btn" id="clearProgress">Reset completion progress</button></div></div>`}
function renderSearch(q){const res=allTopics.filter(t=>(t.title+" "+t.module).toLowerCase().includes(q.toLowerCase())).slice(0,40);$("#content").innerHTML=`<div class="eyebrow">SEARCH THE LEARNING LIBRARY</div><h1 class="page-title">Search results</h1><p class="page-subtitle">${res.length} matching topics for “${esc(q)}”.</p><div class="topic-list">${res.map(t=>`<button class="topic-link" data-topic="${esc(t.title)}"><div><b>${esc(t.title)}</b><small>${esc(t.module)}</small></div><span>→</span></button>`).join("")||`<div class="empty-state"><b>No matching topic found</b>Try “isomerism”, “SN1”, “benzene”, or “carbonyl”.</div>`}</div>`}
function showToast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2400)}
document.addEventListener("click",e=>{const view=e.target.closest("[data-view]");if(view){setView(view.dataset.view);return}const mod=e.target.closest("[data-module]");if(mod){openModule(Number(mod.dataset.module));return}const topic=e.target.closest("[data-topic]");if(topic){openTopic(topic.dataset.topic);return}const comp=e.target.closest("[data-complete]");if(comp){const t=comp.dataset.complete;completed=completed.includes(t)?completed.filter(x=>x!==t):[...completed,t];save();renderTopic(t);showToast(completed.includes(t)?"Topic marked complete":"Completion removed");return}const bm=e.target.closest("[data-bookmark]");if(bm){const t=bm.dataset.bookmark;bookmarks=bookmarks.includes(t)?bookmarks.filter(x=>x!==t):[...bookmarks,t];save();renderTopic(t);showToast(bookmarks.includes(t)?"Topic bookmarked":"Bookmark removed");return}const a=e.target.closest("[data-answer]");if(a){answerQuiz(Number(a.dataset.answer));return}const quick=e.target.closest("[data-quick]");if(quick){document.querySelectorAll("[data-quick]").forEach(b=>{b.disabled=true;if(b.dataset.correct==="true")b.classList.add("correct");else if(b===quick)b.classList.add("wrong")});$("#quickFeedback").innerHTML=`<div class="feedback">${esc(quick.dataset.why)}</div>`;return}const rx=e.target.closest("[data-reaction]");if(rx){document.querySelectorAll("[data-reaction]").forEach(b=>b.disabled=true);$("#reactionFeedback").innerHTML=`<div class="feedback">${rx.dataset.reaction==="right"?"Correct. Markovnikov orientation gives mainly 2-bromopropane under ordinary ionic conditions.":"Not quite. The usual ionic pathway forms the more stable secondary carbocation, leading mainly to 2-bromopropane."}</div>`;return}});
document.addEventListener("click",e=>{if(e.target.id==="nextQuestion")nextQuiz();if(e.target.id==="restartQuiz"){quizIndex=0;quizScore=0;renderQuiz()}if(e.target.id==="calcFormula")runFormula();if(e.target.id==="saveNote"){notes[currentTopic]=$("#topicNote").value;save();showToast("Notes saved on this device")}if(e.target.id==="clearProgress"){if(confirm("Reset all completed topics on this device?")){completed=[];save();renderNotes();showToast("Progress reset")}}});
$("#sidebarSearch").addEventListener("keydown",e=>{if(e.key==="Enter"){if(!e.target.value.trim())return;currentView="search";renderSearch(e.target.value.trim());$("#crumbCurrent").textContent="Search results"}});$("#sidebarSearch").addEventListener("input",e=>{if(e.target.value.trim().length>=2){currentView="search";renderSearch(e.target.value.trim());$("#crumbCurrent").textContent="Search results"}});
document.addEventListener("input",e=>{if(e.target.id==="formulaInput"){}if(e.target.id==="fgSearch")runFG(e.target.value)});document.addEventListener("change",e=>{if(e.target.id==="nameSelect")runName();if(e.target.id==="languageSelect"&&currentView==="topic")renderTopic(currentTopic)});
$("#themeToggle").addEventListener("click",()=>{document.body.classList.toggle("dark-mode");localStorage.setItem("ocm_dark",document.body.classList.contains("dark-mode"))});if(localStorage.getItem("ocm_dark")==="true")document.body.classList.add("dark-mode");
$("#mobileMenu").addEventListener("click",()=>$("#sidebar").classList.toggle("open"));$("#dailyStudy").addEventListener("click",()=>openTopic("Definition of Isomerism"));document.addEventListener("keydown",e=>{if(e.key==="/"&&!["INPUT","TEXTAREA"].includes(document.activeElement.tagName)){e.preventDefault();$("#sidebarSearch").focus()}if(e.key==="Escape")$("#sidebar").classList.remove("open")});
buildNav();moduleCards("#homeModules",8);updateProgress();
